cards.solution:
function ambilSemua<T, K extends keyof T>(daftar: T[], kunci: K): T[K][] {
  return daftar.map((x) => x[kunci]);
}
const menu = [
  { nama: "Kopi", harga: 18000 },
  { nama: "Teh", harga: 8000 },
];
console.log(ambilSemua(menu, "nama").join(", "));
console.log(ambilSemua(menu, "harga").reduce((a, b) => a + b, 0));
